from ute_core.exception import CoreException


class BtsServiceException(CoreException):
    """Base bts services exception"""


class CannotEnableServices(BtsServiceException):
    """Exception raised if response from BTS contains HTTP code different then 200."""


class BtsConnectionError(CoreException):
    """Base bts services exception"""


class NoRouteToHostException(BtsConnectionError):
    """Exception raised if host ip is incorrect"""


class TimeoutParameterException(BtsConnectionError):
    """Exception raised if timeout parameter is not correct"""
